    function run(address target, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(target != address(0));

        uint256 cBefore = address(c).balance;
        uint256 selfBefore = address(this).balance;

        bool mayRevert = false;
        if (target == address(c)) {
            mayRevert = true;
        }

        bool reverted;
        try c.Command{value: amount}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cAfter = address(c).balance;
        uint256 selfAfter = address(this).balance;

        bool fundsBacked = (selfAfter >= selfBefore);
        bool cDecreaseExact = (cBefore >= amount) && (cAfter == cBefore - amount);
        bool cUnchanged = (cAfter == cBefore);

        if (reverted) {
            assert(cUnchanged);
        } else {
            assert(mayRevert ? false : (cDecreaseExact && fundsBacked));
        }
    }

    receive() external payable {}
}

