contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, address adr) public payable {
        require(address(this).balance >= amount);

        // A transfer to a contract address only fails when the receiving contract's
        // fallback/receive reverts. The test contract's receive() never reverts, so
        // when adr is this contract (or an EOA) the transfer cannot fail.
        bool willSend = amount >= address(c).balance;
        bool transferMightRevert = willSend;

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (transferMightRevert) {
            // The deciding call either completes, in which case the contract has sent
            // its entire pre-call balance plus the incoming value and now holds zero,
            // or it reverts because the transfer failed, in which case the whole
            // transaction is reverted and the contract's balance is unchanged.
            assert(reverted ? address(c).balance == address(c).balance : address(c).balance == 0);
        } else {
            // No transfer is attempted: the call cannot revert.
            assert(!reverted);
        }
    }

    receive() external payable {}
}

